import java.util.*;class Solution{public String rearrangeString(String s,int k){if(k<=1)return s;int[]c=new int[26];for(char x:s.toCharArray())c[x-'a']++;PriorityQueue<int[]>pq=new PriorityQueue<>((a,b)->b[0]-a[0]);for(int i=0;i<26;i++)if(c[i]>0)pq.add(new int[]{c[i],i});Queue<int[]>q=new ArrayDeque<>();StringBuilder o=new StringBuilder();for(int pos=0;pos<s.length();pos++){while(!q.isEmpty()&&q.peek()[0]<=pos){int[]x=q.remove();pq.add(new int[]{x[1],x[2]});}if(pq.isEmpty())return"";int[]x=pq.remove();o.append((char)('a'+x[1]));if(--x[0]>0)q.add(new int[]{pos+k,x[0],x[1]});}return o.toString();}}
